  const secondaryKey = config.secondaryControl !== "none" ? config.secondaryKeyboard : void 0;
  const comboLabel = secondaryKey ? `${primaryKey.label}+${secondaryKey.label}` : primaryKey.label;
  const rows = secondaryKey && secondaryKey.row !== primaryKey.row ? `${primaryKey.row}/${secondaryKey.row}` : String(primaryKey.row);
  const secondaryCheck = secondaryKey ? buildBitmapAirDashKeyCheck(secondaryKey) : "";
